/* Old Bear Hunt deep links (dey.ci/#sqrt etc.) now land here; the guide
   moved to /bear-hunt/. Redirect the section hashes so bookmarks and
   shared links keep working. */
(function () {
  var h = location.hash;
  if (!h) return;
  var id = h.slice(1);
  var BH_SECTIONS = ['top', 'model', 'sqrt', 'rally', 'marches', 'timing', 'mix', 'heroes', 'rewards', 'cap', 'rules'];
  if (BH_SECTIONS.indexOf(id) !== -1) location.replace('bear-hunt/' + h);
})();
